// Conceptual sketch of CFS's next-process choice
// (the real scheduler keeps runnable processes in a red-black tree
// ordered by vruntime; this just shows the underlying idea)

function pick_next_process(runnable_processes) {
    return min_by(runnable_processes, p => p.vruntime);
}

